=<!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Emissão de documentos</title>
<style>:root { --cor: {{ $json.cor }}; } {{ $json.css }}
.doc { display: flex; align-items: center; gap: 12px; padding: 12px 0; border-top: 1px solid #ebe9f2; }
.doc > div { flex: 1; min-width: 0; }
.doc strong { display: block; }
.doc span { color: #6b6880; font-size: .88rem; }
.selo { font-size: .75rem; font-weight: 600; padding: 2px 8px; border-radius: 99px; margin-left: 6px; }
.selo.ativo { background: #e6f4ea; color: #1d6b3f; } .selo.outro { background: #fdecea; color: #b3261e; }
.aviso { color: #b3261e; font-size: .85rem; }
.doc input { width: 20px; height: 20px; accent-color: var(--cor); flex: none; }
.doc .vazio { width: 20px; flex: none; }
.botoes { display: flex; gap: 8px; flex-wrap: wrap; }
@media (max-width: 560px) { .doc { flex-wrap: wrap; } .doc .btn, .doc .aviso { width: 100%; text-align: center; } .botoes .btn { flex: 1; text-align: center; } }
</style>
</head>
<body>
<header class="topo"><div>{{ $json.logo_url ? '<img src="' + $json.logo_url + '" alt="">' : '' }}<b>Emissão de documentos</b><small>{{ $json.email }}</small></div></header>
<main>
{{ $json.erro ? '<div class="erro">' + $json.erro + '</div>' : '' }}
{{ $json.lote ? '<div class="ok"><span><strong>' + $json.lote.total + ' documentos cadastrados.</strong></span><span class="botoes">' + $json.lote.zips.map(z => '<a class="btn" href="' + z.href + '">' + z.rotulo + '</a>').join('') + '</span></div>' : '' }}
{{ $json.criado ? '<div class="ok"><span><strong>Documento cadastrado:</strong> ' + $json.criado.nome + '</span><a class="btn" href="' + $json.criado.href + '">Baixar PDF</a></div>' : '' }}
<div class="card">
  <div class="barra"><h1>Documentos ({{ $json.docs.length }})</h1><span class="botoes"><button class="btn claro" type="submit" form="sel">Baixar marcados (ZIP)</button><a class="btn claro" href="?importar">Importar CSV</a><a class="btn" href="?novo">+ Novo documento</a></span></div>
  <p class="muted">Os mais recentes primeiro. O PDF é gerado na hora, a partir da planilha. Para baixar vários de uma vez, marque até {{ $json.limite_zip }} e use "Baixar marcados (ZIP)".</p>
  <form id="sel" method="get" action="">
  {{ $json.docs.map(d => `<div class="doc">${d.id ? `<input type="checkbox" name="zip" value="${d.id}" aria-label="Marcar ${d.nome}">` : '<span class="vazio"></span>'}<div><strong>${d.nome}</strong><span>${[d.tipo, d.curso, d.data].filter(Boolean).join(' · ')}</span><span class="selo ${d.ativo ? 'ativo' : 'outro'}">${d.status}</span></div>${d.problema ? `<span class="aviso">${d.problema}</span>` : `<a class="btn" href="${d.href}">Baixar PDF</a>`}</div>`).join('') }}
  </form>
</div>
</main>
</body>
</html>
